import { Button } from "@heroui/react";
import { useState } from "react";
import type { Locale, Schema } from "../app/types";
import { hotkeyFromEvent, joinHotkey, splitHotkey } from "../utils/hotkeys";
import { DeckIcon } from "./DeckIcon";

export function HotkeyInput({ value, catalog, locale, onChange }: { value: string; catalog: Schema["keys"]; locale: Locale; onChange: (value: string) => void }) {
  const [listOpen, setListOpen] = useState(false);
  const parsed = splitHotkey(value, catalog);
  const label = [
    ...parsed.modifiers.map((name) => catalog.modifiers.find((item) => item.name === name)?.[locale === "fr" ? "label_fr" : "label_en"] ?? name),
    catalog.keys.find((item) => item.name === parsed.key)?.[locale === "fr" ? "label_fr" : "label_en"] ?? parsed.key.toUpperCase(),
  ].filter(Boolean).join(" + ");
  return <div className="hotkey-editor">
    <button className="hotkey-capture" type="button" onKeyDown={(event) => { event.preventDefault(); const next = hotkeyFromEvent(event.nativeEvent, catalog); if (next) onChange(next); }}>
      <DeckIcon name="star" size={17} /><span>{label || (locale === "fr" ? "Cliquez puis appuyez sur les touches" : "Click, then press the keys")}</span>
    </button>
    <Button variant="ghost" size="sm" onPress={() => setListOpen((open) => !open)}>{locale === "fr" ? "Choisir" : "Choose"}</Button>
    {listOpen && <div className="hotkey-options">
      <div className="modifier-options">{catalog.modifiers.map((modifier) => { const active = parsed.modifiers.includes(modifier.name); return <button type="button" className={active ? "active" : ""} key={modifier.name} onClick={() => onChange(joinHotkey(active ? parsed.modifiers.filter((name) => name !== modifier.name) : [...parsed.modifiers, modifier.name], parsed.key, catalog))}>{modifier[locale === "fr" ? "label_fr" : "label_en"]}</button>; })}</div>
      <select aria-label={locale === "fr" ? "Touche" : "Key"} value={parsed.key} onChange={(event) => onChange(joinHotkey(parsed.modifiers, event.target.value, catalog))}>
        <option value="">—</option>{catalog.keys.map((key) => <option key={key.name} value={key.name}>{key[locale === "fr" ? "label_fr" : "label_en"]}</option>)}
        <optgroup label="A–Z">{"abcdefghijklmnopqrstuvwxyz".split("").map((key) => <option key={key} value={key}>{key.toUpperCase()}</option>)}</optgroup>
        <optgroup label="0–9">{"0123456789".split("").map((key) => <option key={key} value={key}>{key}</option>)}</optgroup>
      </select>
    </div>}
  </div>;
}
